import{assert}from"chrome://resources/js/assert.js";import{sendWithPromise}from"chrome://resources/js/cr.js";function requestAutocompleteActionPredictorDb(){sendWithPromise("requestAutocompleteActionPredictorDb").then(updateAutocompleteActionPredictorDb)}function updateAutocompleteActionPredictorDb(database){const filter=document.body.querySelector("#filter");assert(filter);filter.disabled=false;filter.onchange=function(){updateAutocompleteActionPredictorDbView(database)};updateAutocompleteActionPredictorDbView(database)}function updateAutocompleteActionPredictorDbView(database){const databaseSection=document.body.querySelector("#databaseTableBody");assert(databaseSection);const showEnabled=database.enabled&&!!database.db;const enabledMode=document.body.querySelector("#autocompleteActionPredictorEnabledMode");const disabledMode=document.body.querySelector("#autocompleteActionPredictorDisabledMode");assert(enabledMode);assert(disabledMode);enabledMode.hidden=!showEnabled;disabledMode.hidden=showEnabled;if(!showEnabled){return}const filter=document.body.querySelector("#filter");assert(filter);databaseSection.textContent="";for(let i=0;i<database.db.length;++i){const entry=database.db[i];if(!filter.checked||entry.confidence>0){const row=document.createElement("tr");row.className=entry.confidence>.8?"action-prerender":entry.confidence>.5?"action-preconnect":"action-none";row.appendChild(document.createElement("td")).textContent=entry.user_text;row.appendChild(document.createElement("td")).textContent=entry.url;row.appendChild(document.createElement("td")).textContent=entry.hit_count.toString();row.appendChild(document.createElement("td")).textContent=entry.miss_count.toString();row.appendChild(document.createElement("td")).textContent=entry.confidence.toString();databaseSection.appendChild(row)}}const banner=document.body.querySelector("#countBanner");assert(banner);banner.textContent="Entries: "+databaseSection.children.length}document.addEventListener("DOMContentLoaded",requestAutocompleteActionPredictorDb);